#!/usr/bin/env python3
# Generator for the DISC test copy. Injects exact question data from reference.
import io

HTML = r'''<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Бесплатный тест DISC для руководителей</title>
<style>
  :root{
    --bg:#f6f7fb;--card:#fff;--ink:#1c2230;--muted:#5c667a;--line:#e3e7f0;
    --accent:#5b4bd4;--accent-ink:#fff;--accent-soft:#efeefc;
    --d:#e43f4a;--i:#f5a623;--s:#4caf7d;--c:#3f8fdc;
    --radius:14px;--shadow:0 6px 24px rgba(20,26,40,.08);
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0}
  body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;background:var(--bg);color:var(--ink);line-height:1.5;-webkit-font-smoothing:antialiased}
  .wrap{max-width:1080px;margin:0 auto;padding:30px 20px 60px}
  .landing{text-align:center;background:var(--card);border:1px solid var(--line);border-radius:22px;padding:52px 28px;box-shadow:var(--shadow)}
  .landing .brand{display:inline-flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.2px;color:var(--accent);text-transform:uppercase;font-size:13px;margin-bottom:22px}
  .landing h1{font-size:clamp(26px,4vw,40px);margin:0 0 14px;line-height:1.15;font-weight:800}
  .landing p{max-width:640px;margin:0 auto 28px;color:var(--muted);font-size:17px}
  .btn{border:none;cursor:pointer;font:inherit;font-weight:700;border-radius:12px;padding:15px 30px;transition:transform .08s ease,box-shadow .2s,background .2s}
  .btn:active{transform:translateY(1px)}
  .btn--primary{background:var(--accent);color:var(--accent-ink);box-shadow:0 8px 22px rgba(91,75,212,.32)}
  .btn--primary:hover{background:#4c3dbe}
  .btn--ghost{background:transparent;color:var(--ink);border:1px solid var(--line);box-shadow:none}
  .btn--ghost:hover{background:var(--accent-soft)}
  .btn:disabled{opacity:.45;cursor:not-allowed}
  .hint{text-align:center;margin-top:16px;color:var(--muted);font-size:14px}
  .modal{position:fixed;inset:0;z-index:100;display:none}
  .modal.is-open{display:block}
  .modal__overlay{position:absolute;inset:0;background:rgba(18,22,33,.55);backdrop-filter:blur(2px)}
  .modal__dialog{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(880px,calc(100% - 40px));max-height:calc(100% - 40px);overflow:hidden;background:var(--card);border-radius:20px;box-shadow:0 24px 60px rgba(10,14,26,.32);display:flex;flex-direction:column}
  .modal__close{position:absolute;top:14px;right:16px;width:34px;height:34px;border:none;background:transparent;cursor:pointer;font-size:26px;line-height:1;color:var(--muted);z-index:5;border-radius:8px}
  .modal__close:hover{background:var(--accent-soft);color:var(--accent)}
  .modal__head{padding:26px 28px 8px}
  .modal__title{margin:0;font-size:24px;font-weight:800}
  .modal__sub{margin:8px 0 0;color:var(--muted);font-size:15px;font-style:italic}
  .modal__lead{margin:14px 0 0;padding:12px 16px;background:var(--accent-soft);border-radius:10px;color:var(--ink);font-size:14.5px;font-weight:500}
  .tabs{display:flex;gap:6px;padding:20px 28px 4px;flex-wrap:wrap}
  .tab{border:1px solid var(--line);background:#fff;color:var(--muted);border-radius:999px;padding:7px 15px;font-size:13.5px;cursor:pointer;font-weight:600;transition:all .15s}
  .tab:hover{border-color:var(--accent);color:var(--accent)}
  .tab.is-active{background:var(--accent);color:#fff;border-color:var(--accent)}
  .modal__body{padding:10px 28px 8px;overflow:auto}
  .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:8px}
  @media (max-width:720px){.grid{grid-template-columns:1fr}}
  .card{border:1px solid var(--line);border-radius:14px;padding:12px 12px 14px;background:#fff;display:flex;flex-direction:column;min-height:150px}
  .card__title,.card__foot{font-size:12.5px;font-weight:700;letter-spacing:.3px;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;justify-content:space-between}
  .card__foot{margin-top:10px}
  .card__foot .dot{width:8px;height:8px;border-radius:50%;background:var(--accent);opacity:.5}
  .grid ul,li{margin:0;padding:0;list-style:none}
  .list{margin:6px 0 0;min-height:96px;display:flex;flex-direction:column;gap:6px;padding:4px;background:#fbccff;border-radius:10px}
  .list .is-over{box-shadow:0 0 0 2px var(--accent)}
  .item{display:flex;align-items:center;gap:10px;padding:9px 12px;background:#fff;border:1px solid var(--line);border-radius:10px;cursor:grab;font-size:15px;font-weight:500;transition:box-shadow .12s,transform .06s;user-select:none}
  .item:active{cursor:grabbing}
  .item.is-dragging{box-shadow:0 10px 24px rgba(20,26,40,.16);z-index:5}
  .item .no{flex:0 0 auto;width:22px;height:22px;border-radius:50%;background:var(--accent-soft);color:var(--accent);font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center}
  .item .text{flex:1}
  .item .handle{flex:0 0 auto;color:var(--muted);opacity:.55;cursor:grab;display:flex}
  .item .handle:hover{opacity:1}
  @media (pointer:fine){.item .handle{display:none}}
  @media (pointer:coarse){.item{cursor:default}.item .no,.item .text{pointer-events:none}}
  .progress{height:7px;background:var(--line);border-radius:99px;margin:18px 28px 0;overflow:hidden}
  .progress__bar{height:100%;background:linear-gradient(90deg,var(--accent),#8a7bff);width:12.5%;transition:width .35s ease}
  .actions{display:flex;justify-content:space-between;align-items:center;padding:18px 28px 22px;gap:12px}
  .actions .spacer{flex:1}
  .step-label{font-size:13.5px;color:var(--muted);font-weight:600}
  .actions .nav{display:flex;gap:10px}
  .result{max-width:780px;margin:0 auto}
  .result-card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:34px 32px;box-shadow:var(--shadow)}
  .result-card .lead{margin:0 0 22px}
  .scores{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}
  @media (max-width:560px){.scores{grid-template-columns:repeat(2,1fr)}}
  .score{border:1px solid var(--line);border-radius:14px;padding:16px 12px;text-align:center;position:relative;overflow:hidden}
  .score .ring{position:absolute;inset:0;bottom:0;height:0;transition:height .6s ease;opacity:.12}
  .score .type{font-weight:800;font-size:15px;letter-spacing:.4px;position:relative}
  .score .val{font-size:30px;font-weight:800;margin:6px 0 2px;position:relative}
  .score .name{font-size:12.5px;color:var(--muted);position:relative}
  .score.d .ring{background:var(--d)}
  .score.i .ring{background:var(--i)}
  .score.s .ring{background:var(--s)}
  .score.c .ring{background:var(--c)}
  .score.d .type,.score.d .val{color:var(--d)}
  .score.i .type,.score.i .val{color:var(--i)}
  .score.s .type,.score.s .val{color:var(--s)}
  .score.c .type,.score.c .val{color:var(--c)}
  .desc{color:var(--muted);font-size:14.5px;margin:0 0 22px}
  .disclaimer{background:#fffbe6;border:1px solid #f0e3a8;border-radius:12px;padding:16px 18px;font-size:13.5px;color:#6b5a1e;margin-top:22px}
  .disclaimer b{color:#4a3d0f}
  .actions-row{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}
  .footer-note{text-align:center;color:var(--muted);font-size:13px;margin-top:26px}
  .hidden{display:none !important}
  @media not all and (display-optimal){.modal__dialog{width:min(880px,100%)}}
</style>
</head>
<body>
<div class="wrap">

  <section class="landing" id="landing">
    <span class="brand">
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
        <rect x="2" y="2" width="9" height="9" rx="2" fill="var(--d)"/>
        <rect x="13" y="2" width="9" height="9" rx="2" fill="var(--i)"/>
        <rect x="2" y="13" width="9" height="9" rx="2" fill="var(--s)"/>
        <rect x="13" y="13" width="9" height="9" rx="2" fill="var(--c)"/>
      </svg>DISC
    </span>
    <h1>Бесплатный тест DISC для руководителей</h1>
    <p>Определите свой лидерский стиль за пару минут. Тест из 24 вопросов: в каждом нужно располоить прилагательные в порядке «наиболее — наименее о себе». Результат сразу на странице.</p>
    <button class="btn btn--primary" id="openBtn" type="button">Пройти тест</button>
    <div class="hint">Около 3 минут · никаких регистраций · работает офлайн</div>
  </section>

  <section class="result hidden" id="result">
    <div class="result-card">
      <h2>Ваш DISC-профиль:</h2>
      <p class="lead" id="resultLead">Тест завершён. Вот ваша раскладка по типам; баллы от −24 до +24.</p>
      <div class="scores" id="scores">
        <div class="score d"><span class="ring"></span><div class="type">D</div><div class="val">0</div><div class="name">Доминирование</div></div>
        <div class="score i"><span class="ring"></span><div class="type">I</div><div class="val">0</div><div class="name">Влияние</div></div>
        <div class="score s"><span class="ring"></span><div class="type">S</div><div class="val">0</div><div class="name">Устойчивость</div></div>
        <div class="score c"><span class="ring"></span><div class="type">C</div><div class="val">0</div><div class="name">Соответствие</div></div>
      </div>
      <p class="desc" id="desc"></p>
      <p class="desc" id="descMore"></p>
      <div class="disclaimer">
        <b>Обратите внимание:</b> мы не даём расшифровку ваших индивидуальных результатов.
        Вместо этого мы помогаем вам научиться использовать этот инструмент для самотестирования,
        а также для работы с вашими командами, сотрудниками и коллегами.
      </div>
      <div class="actions-row">
        <button class="btn btn--ghost" id="restartBtn" type="button">Пройти ещё раз</button>
      </div>
    </div>
