</div>

<script>
/* ============================================================
   DISC — самодостаточная копия. Офлайн, без внешних запросов.
   ============================================================ */
(function(){
  "use strict";

<%QUESTIONS_BLOCK%>

  var TYPES = {
    d:{name:"Доминирование", short:"Смелый, прямоли нейный (д, результат-ориентированный лидер.",
            full:"D (Доминирование). Люди, сосредоточенные на результате: прямолинейные, уверенные, готовы принимать решения и вести за собой. Им важна власть, вызовы и быстрые результаты."},
    i:{name:"Влияние", short:"Энергичный, общительный, оптимичный, вдохновляющий.",
            full:"I (Влияние). Энергичные, оптимистичные и общительные люди. Любят команду, легко общаются, умеют вдохновлять других. Ценят признание и живую атмосферу."},
    s:{name:"Устойчивость", short:"Спокойный, надёжный, терпеливый, верный, стабильный.",
            full:"S (Устойчивость). Спокойные, терпеливые и надёжные люди. Хорошие слушатели, предсказуемы, ценят стабильность и надёжные отношения. Часто это «связующее звено» команды."},
    c:{name:"Соответствие", short:"Ответственный, аккуратный, аналитический, сосредоточенный на деталях.",
            full:"C (Соответствие). Ответственные, аккуратные и аналитические люди. Важны качество, точность, стандарты и правильное выполнение работы."}
  };
  var ORDER = ["d","i","s","c"];
  var STEPS = 8;
  var NAMES = ["Первый","Второй","Третий","Четвертый","Пятый","Шестой","Седьмой","Восьмой"];
  var $ = function(s){return document.querySelector(s);};
  var $$ = function(s){return Array.from(document.querySelectorAll(s));};

  var step = 0;
  var answered = {};
  var wizard = $("#wizard"), grid = $("#grid"), tabs = $("#tabs");
  var bodyEl = $("#body");

  function openModal(){ wizard.classList.add("is-open"); wizard.setAttribute("aria-hidden","false"); document.documentElement.style.overflow="hidden"; render(); }
  function closeModal(){ wizard.classList.remove("is-open"); wizard.setAttribute("aria-hidden","true"); document.documentElement.style.overflow=""; }

  function buildQuestions(){ tabs.innerHTML=""; grid.innerHTML="";
    for(var st=0; st<STEPS; st++){
      var tab=document.createElement("button"); tab.type="button"; tab.className="tab"; tab.setAttribute("role","tab"); tab.setAttribute("aria-selected","false"); tab.dataset.step=st; tab.textContent=NAMES[st];
      tab.addEventListener("click", function(){ goTo(Number(this.dataset.step)); });
      tabs.appendChild(tab);
    }
  }

  function makeItem(item){
    var li=document.createElement("li"); li.className="item"; li.dataset.type=item.type; li.draggable=true;
    li.innerHTML='<span class="no"></span><span class="text"></span>';
    li.querySelector(".text").textContent=item.text;
    return li;
  }
  function handleSvg(){ return '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="5" cy="3" r="1.4"/><circle cx="11" cy="3" r="1.4"/><circle cx="5" cy="8" r="1.4"/><circle cx="11" cy="8" r="1.4"/><circle cx="5" cy="13" r="1.4"/><circle cx="11" cy="13" r="1.4"/></svg>'; }

  function renderStep(st){
    var pane=grid.querySelector("[data-pane="+st+"]");
    pane.innerHTML="";
    QUESTIONS.forEach(function(q){
      if(q.step!==st) return;
      var card=document.createElement("div"); card.className="card";
      var ul=document.createElement("ul"); ul.className="list"; ul.dataset.qi=QUESTIONS.indexOf(q);
      var order=answered[QUESTIONS.indexOf(q)];
      var seq=order?order.map(function(t){return {type:t};}):q.items.slice();
      seq.forEach(function(it){ ul.appendChild(makeItem(it)); });
      card.innerHTML='<div class="card__title">Я наиболее</div>';
      card.appendChild(ul);
      card.insertAdjacentHTML("beforeend", '<div class="card__foot"><span>Я наименее</span><span class="dot"></span></div>');
      if(ul.querySelector(".handle")===null){ var h=document.createElement("span"); h.className="handle"; h.setAttribute("aria-hidden","true"); h.innerHTML=handleSvg(); ul.insertBefore(h, ul.firstChild); }
      pane.appendChild(card);
    });
  }

  function syncScores(){ $$(".list").forEach(function(ul){ answered[ul.dataset.qi]=[].slice.call(ul.children).map(function(li){return li.dataset.type;}); }); }

  /* drag and drop (desktop + fine touch) */
  function attachDraggable(ul){
    ul.addEventListener("dragstart",function(ev){
      var dragging=ev.target.closest(".item"); dragging.classList.add("is-dragging"); ev.dataTransfer.setData("text/plain",""); ev.dataTransfer.effectAllowed="move";
      ul.querySelectorAll(".is-over").forEach(function(x){x.classList.remove("is-over");});
    });
    ul.addEventListener("dragend",function(){ draggingEl=null; syncScores(); });
    ul.addEventListener("dragover",function(ev){ ev.preventDefault();
      var dragging=ul.querySelector(".is-dragging"); if(!dragging||dragging===ev.target.closest(".item")) return;
      var after=afterEl(ul, ev.clientY); if(after==null) ul.appendChild(dragging); else ul.insertBefore(dragging, after);
    });
    dragoverUl=ul;
  }
  var draggingEl=null, dragoverUl=null;
  function afterEl(ul,y){ var items=[].slice.call(ul.children).filter(function(c){return !c.classList.contains("is-dragging");}); return items; }
  function afterAt(ul,y){ var items=[].slice.call(ul.children).filter(function(c){return !c.classList.contains("is-dragging");});
    var half=items.map(function(c){return c.getBoundingClientRect().top + c.offsetHeight/2;});
    for(var i=0;i<half.length;i++){ if(y<half[i]) return items[i]; } return null; }
  function insertBeforeDrag(ul, after){ var dragging=ul.querySelector(".is-dragging"); if(dragging===null) return; if(after==null) ul.appendChild(dragging); else ul.insertBefore(dagging, after); }

  function makeSortable(ul){
    ul.addEventListener("dragover",function(ev){ ev.preventDefault();
      var dragging=ul.querySelector(".is-dragging"); if(!dragging) return;
      var after=afterAt(ul, ev.clientY); if(after==null) ul.appendChild(dragging); else ul.insertBefore(dragging, after);
      ul.querySelectorAll(".is-over").forEach(function(x){x.classList.remove("is-over");});
    });
  }
  function isTouch(){ return ("ontouchstart" in window) || (navigator.maxTouchPoints>1); }
  function attachSortable(){ $$(".list").forEach(function(ul){ makeSortable(ul); ul.addEventListener("dragstart",function(ev){ ev.target.closest(".item").classList.add("is-dragging"); ev.dataTransfer.effectAllowed="move"; draggingEl=ev.target.closest(".item"); }); ul.addEventListener("dragend",function(){ draggingEl=null; syncScores(); }); }); }

  function goTo(s){ if(s<0||s>=STEPS) return; step=s; render(); bodyEl.scrollTop=0; }
  function next(){ if(step<STEPS-1) goTo(step+1); }
  function prev(){ if(step>0) goTo(step-1); }
  function skip(){ if(step<STEPS-1) next(); }

  function build(){ tabs.innerHTML=""; buildQuestions();
    for(var st=0; st<STEPS; st++){
      var panes=grid.querySelectorAll("[data-pane]");
      // ensure a pane exists
      var pane=grid.querySelector("[data-pane]");
      if(pane){ for(var i=0;i<STEPS;i++){ var p=grid.querySelector("[data-pane="+(i)+"]"); if(!p){ p=document.createElement("div"); p.setAttribute("data-pane",i); grid.appendChild(p); } } }
    }
  }

  var isMobile = window.matchMedia ? window.matchMedia("(max-width:767px)").matches : false;

  function render(){
    $$(".tab").forEach(function(t){ var active=Number(t.dataset.step)===step; t.classList.toggle("is-active",active); t.setAttribute("aria-selected",active?"true":"false"); });
    renderStep(step);
    attachSortable();
    if(!isMobile){ attachSortable(); }
    else { attachSortable(); }
    $("#bar").style.width=((step+1)/STEPS*100)+"%";
    var back=$("#prevBtn"), next=$("#nextBtn"), finish("#finishBtn");
    if(step===0){ back.disabled=true; } else { back.disabled=false; }
    if(step===STEPS-1){ next.classList.add("hidden"); finish.classList.remove("hidden"); }
    else { next.classList.remove("hidden"); finish.classList.add("hidden"); }
  }

  function score(){
    var maj={d:0,i:0,s:0,c:0}, min={d:0,i:0,s:0,b:0};
    QUESTIONS.forEach(function(q){
      var order=answered[QUESTIONS.indexOf(q)]; if(!order) return;
      var top=order[0]; var bot=(order.length>1)?order[order.length-1]:null;
      if(!top || !(top in maj)) return;
      if(top in maj) { maj[top]++; }
      if(bot && (bot in min)) { min[bot]--; }
    });
    var out={}; ORDER.forEach(function(k){ out[k]=maj[k]-min[k]; });
    return out;
  }
  function showResult(){
    var s=score();
    $("#result").classList.remove("hidden"); wizard.style.display="none";
    var vals={d:s.d,i:s.i,s:s.s,c:s.c};
    var els=$$(".scores .score");
    ORDER.forEach(function(t){
      var i=["d","i","s","c"].indexOf(t);
      var el=els[i]; var v=vals[t];
      el.querySelector(".val").textContent=(v>0?"+":"")+v;
      var ring=el.querySelector(".ring"); var pct=Math.min(100,Math.abs(v)/24*100);
      setTimeout(function(){ ring.style.height=pct+"%"; },120);
    });
    var best=ORDER.slice().sort(function(a,b){ return vals[b]-vals[a]; }")[0];
    $("#desc").textContent = TYPES[best].short;
    $("#descMore").textContent = TYPES[best].full;
    document.getElementById("landing").classList.add("hidden");
    window.scrollTo({top:0,behavior:"smooth"});
  }
  function startAgain(){ answered={}; step=0; $("#result").classList.add("hidden"); wizard.classList.remove("hidden"); wizard.style.display=""; $("#landing").classList.remove("hidden"); openModal(); }

  function ready(){
    build(); attachSortable(); render();
    $("#openBtn").addEventListener("click", openModal);
    $("#closeBtn").addEventListener("click", closeModal);
    ["[data-close]"].forEach(function(s){ $(s).addEventListener("click", closeModal); });
    $("#prevBtn").addEventListener("click", prev);
    $("#nextBtn").addEventListener("click", next);
    $("#skipBtn").addEventListener("click", skip);
    $("#finishBtn").addEventListener("click", function(){ closeModal(); showResult(); });
    $("#restartBtn").addEventListener("click", startAgain);
    document.addEventListener("keydown",function(ev){ if(ev.key==="Escape") closeModal(); });
  }
  if(document.readyState==="loading"){ document.addEventListener("DOMContentLoaded", ready); }
  else { ready(); }
})();
</script>
</body>
</html>

