}
function setStep(n){
  n=Math.max(0,Math.min(STEPS-1,n));
  currentStep=n;
  render();
  bodyEl.scrollTop=0;
}
function next(){setStep(currentStep+1);}
function prev(){setStep(currentStep-1);}
function skipBtn(){setStep(currentStep+1);}
function makeItem(type,qi,text){
  var li=document.createElement("li");
  li.className="item";
  li.dataset.type=type;
  li.dataset.qi=qi;
  li.draggable=true;
  var no=document.createElement("span");no.className="no";
  var handle=document.createElement("span");handle.className="handle";
  handle.innerHTML=handleSvg();
  var t=document.createElement("span");t.className="text";t.textContent=text;
  li.appendChild(li);li.appendChild(handle);li.appendChild(t);
  return li;
}
function handleSvg(){
  return '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="5" cy="3" r="1.4" fill="currentColor"/><circle cx="11" cy="3" r="1.4" fill="currentColor"/><circle cx="5" cy="8" r="1.4" fill="currentColor"/><circle cx="11" cy="8" r="1.4" fill="currentColor"/><circle cx="5" cy="13" r="1.4" fill="currentColor"/><circle cx="11" cy="13" r="1.4" fill="currentColor"/></svg>';
}
function makeList(qi,items){
  var ul=document.createElement("ul");
  ul.className="list";
  ul.dataset.qi=qi;
  items.forEach(function(item){ul.appendChild(makeItem(item.type,qi,item.text));});
  return ul;
}
function makeCard(qi){
  var query=QUESTIONS[qi];
  var card=document.createElement("div");
  card.className="card";
  var title=document.createElement("div");title.className="card__title";
  title.textContent="Я наиболее";card.appendChild(title);
  card.appendChild(makeList(qi,query.items));
  var foot=document.createElement("div");foot.className="card__foot";
  foot.innerHTML='<span>Я наименее</span><span class="dot"></span>';
  card.appendChild(foot);
  return card;
}
function score(){
  var maj={d:0,i:0,s:0,c:0};var min={d:0,i:0,s:0,c:0};
  QUESTIONS.forEach(function(query,qi){
    var arr=answered[qi];
    if(!arr)return;
    var q=QUESTIONS[qi];
    if(arr[0])maj[arr[0]]++;
    if(arr[arr.length-1])min[arr[arr.length-1]]++;
  });
  var out={};
  ORDER.forEach(function(k){out[k]=maj[k]-min[k];});
  return out;
}
function collect(){
  answered=[];
  qsa("ul.list").forEach(function(ul){
    var seq=[];
    Array.prototype.forEach.call(ul.children,function(el){
      seq.push(el.dataset.type);
    });
    answered[parseInt(ul.dataset.qi,10)]=seq;
  });
}
function render(){
  qsa("#tabs .tab",tabs).forEach(function(tab){
    tab.classList.toggle("is-active",parseInt(tab.dataset.step,10)===currentStep);
    tab.setAttribute("aria-selected",String(parseInt(tab.dataset.step,10)===currentStep));
  });
  grid.innerHTML="";
  var gridWrap=document.createElement("div");gridWrap.className="grid";
  QUESTIONS.forEach(function(query,qi){
    if(query.step===currentStep)gridWrap.appendChild(makeCard(qi));
  });
  grid.appendChild(gridWrap);
  barEl.style.width=((currentStep+1)/STEPS*100)+"%";
  document.getElementById("prevBtn").disabled=currentStep===0;
  if(currentStep===STEPS-1){
    document.getElementById("nextBtn").style.display="none";
    document.getElementById("finishBtn").style.display="";
  }else{
    document.getElementById("nextBtn").style.display="";
    document.getElementById("finishBtn").style.display="none";
  }
}
function makeSortable(){
  document.body.addEventListener("dragstart",function(e){
    var li=e.target.closest?e.target.closest(".item"):null;
    if(!li)return;
    dragging=li;li.classList.add("is-dragging");
    e.dataTransfer.effectAllowed="move";
    e.dataTransfer.setData("text/plain","");
  });
  document.body.addEventListener("dragend",function(e){
    if(dragging){dragging.classList.remove("is-dragging");dragging=null;}
    collect();
  });
  document.body.addEventListener("dragover",function(e){
    var ul=e.target.closest?e.target.closest(".list"):null;
    if(!ul||!dragging)return;
    e.preventDefault();
    var after=afterEl(ul,e.clientY);
    if(after==null){ul.appendChild(dragging);}
    else{ul.insertBefore(dragging,after);}
  });
  qsa("ul.list").forEach(function(ul){
    Array.prototype.forEach.call(ul.children,function(li){
      li.addEventListener("keydown",onKey);
    });
  });
}
function onKey(e){
  var li=e.target.closest?e.target.closest(".item"):e.target;
  if(!li||!li.dataset||!li.dataset.qi)return;
  var ul=li.closest?li.closest("ul"):null;
  if(!ul)return;
  var items=Array.prototype.slice.call(ul.children);
  var idx=items.indexOf(li);
  if(e.key==="ArrowUp"){
    if(idx>0){ul.insertBefore(li,items[idx-1]);e.preventDefault();collect();}
  }else if(e.key==="ArrowDown"){
    if(idx<ul.children.length-1){ul.insertBefore(li,items[idx+1].nextSibling)||ul.appendChild(li);e.preventDefault();collect();}
  }
}
function afterEl(ul,y){
  var items=Array.prototype.slice.call(ul.children).filter(function(c){return !c.classList.contains("is-dragging");});
  var center=items.map(function(c){var r=c.getBoundingClientRect();return r.top+r.height/2;});
  for(var i=0;i<center.length;i++){
    if(y<center[i])return items[i];
  }
  return null;
}
var bestKey;
function showResult(){
  var s=score();
  var list=ORDER.slice().sort(function(a,b){return s[b]-s[a];});
  bestKey=list[0];
  var lead=document.getElementById("resultLead");
  lead.innerHTML="Тест завершён. Вот ваша раскладка по типам. Баллы от &#8211;24 до +24 за каждого типа. Сумма баллов всех четырёх типов всегда 0.";
  var best=byKey(bestKey);
  document.getElementById("desc").innerHTML="<strong>Ваш доминирующий тип — «"+best.name+"»:</strong>"+best.full;
  qsa(".scores .score").forEach(function(el){
