      tab.dataset.step=String(i);
      tab.setAttribute("role","tab");
      tab.textContent=STEP_NAMES[i];
      tab.addEventListener("click",function(){setStep(i);});
      tabs.appendChild(tab);
    })(n);
  }
  document.getElementById("openBtn").addEventListener("click",function(e){e.preventDefault();openWizard();});
  document.getElementById("closeBtn").addEventListener("click",function(e){e.preventDefault();closeWizard();});
  qsa("[data-close]").forEach(function(e){e.addEventListener("click",function(ev){ev.preventDefault();closeWizard();});});
  document.getElementById("prevBtn").addEventListener("click",prev);
  document.getElementById("nextBtn").addEventListener("click",next);
  document.getElementById("skipBtn").addEventListener("click",skipBtn);
  document.getElementById("finishBtn").addEventListener("click",function(e){if(e)e.preventDefault();collect();closeWizard();showResult();});
  document.getElementById("restartBtn").addEventListener("click",startAgain);
  document.addEventListener("keydown",function(ev){if(ev.key==="Escape"){closeWizard();}});
  makeSortable();
  render();
});

