var STEPS = 8;

var wizard, grid, tabs, bodyEl, barEl, landingEl, resultEl;
var currentStep = 0;
var answered = [];
var dragging = null;

var $ = function (s) { return document.querySelector(s); };
var $$ = function (s) { return Array.from(document.querySelectorAll(s)); };

function byKey(k) { return TYPES.filter(function (t) { return t.key === k; })[0]; }

function openWizard() {
  wizard.classList.add("is-open");
  wizard.setAttribute("aria-hidden", "true");
  document.documentElement.style.overflow = "hidden";
  render();
}
function closeWizard() {
  wizard.classList.remove("is-open");
  wizard.setAttribute("aria-hidden", "false");
  document.documentElement.style.overflow = "";
}
function setStep(n) {
  n = Math.max(0, Math.min(STEPS - 1, n));
  currentStep = n;
  render();
  bodyEl.scrollTop = 0;
}
function next() { setStep(currentStep + 1); }
function prev() { setStep(currentStep - 1); }
function skipFn() { setStep(currentStep + 1); }

function handleSvg() {
  return '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="5" cy="3" r="1.4" fill="currentColor"/><circle cx="11" cy="3" r="1.4" fill="currentColor"/><circle cx="5" cy="8" r="1.4" fill="currentColor"/><circle cx="11" cy="8" r="1.4" fill="currentColor"/><circle cx="5" cy="13" r="1.4" fill="currentColor"/><circle cx="11" cy="13" r="1.4" fill="currentColor"/></svg>';
}

function makeItem(type, qi, text) {
  var li = document.createElement("li");
  li.className = "item";
  li.dataset.type = type;
  li.dataset.qi = qi;
