  card.appendChild(foot);
  return card;
}

function render() {
  $$("#tabs .tab").forEach(function (tab) {
    var n = parseInt(tab.dataset.step, 10);
    tab.classList.toggle("is-active", n === currentStep);
    tab.setAttribute("aria-selected", String(n === currentStep));
  });
  grid.innerHTML = "";
  QUESTIONS.forEach(function (query, qi) {
    if (query.step === currentStep) grid.appendChild(makeCard(qi));
  });
  barEl.style.width = ((currentStep + 1) / STEPS * 100) + "%";
  $("#prevBtn").disabled = currentStep === 0;
  if (currentStep === STEPS - 1) {
    $("#nextBtn").style.display = "none";
    $("#finishBtn").style.display = "";
  } else {
    $("#nextBtn").style.display = "";
    $("#finishBtn").style.display = "none";
  }
}

function makeSortable() {
  document.body.addEventListener("dragstart", function (e) {
    var li = e.target.closest ? e.target.closest(".item") : null;
    if (!li) return;
    dragging = li;
    li.classList.add("is-dragging");
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", "");
  });
  document.body.addEventListener("dragend", function () {
    if (dragging) { dragging.classList.remove("is-dragging"); dragging = null; }
    collect();
  });
  document.body.addEventListener("dragover", function (e) {
    var ul = e.target.closest ? e.target.closest(".list") : null;
    if (!ul || !dragging) return;
    e.preventDefault();
    var after = afterEl(ul, e.clientY);
    if (after == null) { ul.appendChild(dragging); }
    else { ul.insertBefore(dragging, after); }
  });
  $$("ul.list").forEach(function (ul) {
    Array.prototype.forEach.call(ul.children, function (li) {
      li.addEventListener("keydown", onKey);
    });
  });
}

function onKey(e) {
  var li = e.target.closest ? e.target.closest(".item") : e.target;
  if (!li || !li.dataset || !li.dataset.qi) return;
  var ul = li.closest ? li.closest("ul") : null;
  if (!ul) return;
  var items = Array.prototype.slice.call(ul.children);
  var idx = items.indexOf(li);
  if (e.key === "ArrowUp") {
    if (idx > 0) { ul.insertBefore(li, items[idx - 1]); e.preventDefault(); collect(); }
  } else if (e.key === "ArrowDown") {
    if (idx < ul.children.length - 1) { ul.insertBefore(li, items[idx + 1].nextSibling) || ul.appendChild(li); e.preventDefault(); collect(); }
  }
}

function afterEl(ul, y) {
  var items = Array.prototype.slice.call(ul.children).filter(function (c) { return !c.classList.contains("is-dragging"); });
  var center = items.map(function (c) { var r = c.getBoundingClientRect(); return r.top + r.height / 2; });
  for (var i = 0; i < center.length; i++) { if (y < center[i]) return items[i]; }
  return null;
}

function collect() {
  answered = [];
  $$("ul.list").forEach(function (ul) {
    var order = [];
    Array.prototype.forEach.call(ul.children, function (el) { order.push(el.dataset.type); });
    answered[parseInt(ul.dataset.qi, 10)] = order;
  });
}

function score() {
  var maj = { d: 0, i: 0, s: 0, c: 0 };
  var min = { d: 0, i: 0, s: 0, c: 0 };
  QUESTIONS.forEach(function (query, qi) {
    var arr = answered[qi];
    if (!arr || arr.length < 1) return;
    maj[arr[0]] = (maj[arr[0]] || 0) + 1;
    min[arr[arr.length - 1]] = (min[arr[arr.length - 1]] || 0) + 1;
  });
  var out = {};
  ORDER.forEach(function (k) { out[k] = maj[k] - min[k]; });
  return out;
}

function showResult() {
  collect();
  var s = score();
  var ranked = ORDER.slice().sort(function (a, b) { return s[b] - s[a]; });
  var bestKey = ranked[0];
  $("#resultLead").innerHTML = "Тест завершён. Вот раскладка по типам; баллы от &#8211;24 до +24. Сумма баллов всех четырёх типов = 0.";
  var best = byKey(bestKey);
  $("#desc").innerHTML = "<strong>Ваш доминирующий тип — «" + best.name + "»:</strong> " + best.full;
  $("#descMore").textContent = best.short;
  $$(".scores .score").forEach(function (el) {
    var k = el.dataset.key;
    el.querySelector(".val").textContent = (s[k] > 0 ? "+" : "") + s[k];
  });
  landingEl.classList.add("hidden");
 wizard.style.display = "none";
  resultEl.classList.remove("hidden");
  window.scrollTo({ top: 0, behavior: "smooth" });
}
function startAgain() {
  answered = [];
  currentStep = 0;
  collect();
  resultEl.classList.add("hidden");
  wizard.style.display = "";
  wizard.classList.remove("is-open");
  wizard.classList.remove("hidden");
  landingEl.classList.remove("hidden");
  render();
}
document.addEventListener("DOMContentLoaded", function () {
  wizard = $("#wizard");
  grid = $("#grid");
  tabs = $("#tabs");
  bodyEl = $("#body");
  barEl = $("#bar");
  landingEl = $("#landing");
  resultEl = $("#result");
  for (var n = 0; n < STEPS; n++) {
    (function (i) {
      var tab = document.createElement("button");
      tab.type = "button";
      tab.className = "tab" + (i === 0 ? " is-active" : "");
      tab.tabIndex = 0;
      tab.dataset.step = String(i);
      tab.setAttribute("role", "tab");
      tab.textContent = STEP_NAMES[i];
      tab.addEventListener("click", function () { setStep(i); });
      tabs.appendChild(tab);
    })(n);
  }
  $("#openBtn").addEventListener("click", function (e) { if (e.preventDefault) e.preventDefault(); openWizard(); });
  $("#closeBtn").addEventListener("click", function (e) { if (e.preventDefault) e.preventDefault(); closeWizard(); });
  $$("[data-close]").forEach(function (e) { e.addEventListener("click", function (ev) { if (Ev.preventDefault) ev.preventDefault(); closeWizard(); }); });
  $("#prevBtn").addEventListener("click", prev);
  $("#nextBtn").addEventListener("click", next);
  $("#skipBtn").addEventListener("click", skipFn);
  $("#finishBtn").addEventListener("click", function (e) { if (e.preventDefault) e.preventDefault(); showResult(); });
  $("#restartBtn").addEventListener("click", startAgain);
  document.addEventListener("keydown", function (ev) { if (ev.key === "Escape") closeWizard(); });
  makeSortable();
  render();
});
`;

