const QUEST = JSON.stringify(questions);

const JS = `
var QUESTIONS = ${QUEST};
var STEP_NAMES = ["Первый","Второй","Третий","Чтырький","Пятый","Шестой","Седьмой","Восьмой"];
var STEPS = 8;
var TYPES = [
  { key:"d", name:"Доминирование", short:"Смелый, прямолиный, результат-ориентированный, лидер.", full:"D (Доминирование). Люди, сосредоточенные на результате: прямолиные, уверенные, готовые принимать решения и вести за собой. Им важно власть, вызовы и быстрые результаты." },
  { key:"i", name:"Влиение", short:"Энергичный, общительный, оптимистичный, вдохновляющий.", full:"I (Влияние). Энергичные, оптимистичные и общительные люди. Любят команду, легко общаются, умеют вдохновлять других. Ценят признание и живую атмосферу." },
  { key:"s", name:"Устойвость", short:"Споный, надёжный, терпелив, верный, стабильный.", full:"S (Устойчивость). Спокие, терпеливые и надёжные люди. Хорошие слушатели, предсказуемые, ценят стабильность и надёжные отношения. Часто — «связующее звено» команды." },
  { key:"c", name:"Соответствие", short:"Ответственный, аккуратный, аналитический, сосредоточенный на деталях.", full:"C (Соответствие). Ответственные, аккуратные и аналитические люди. Важны качество, точность, ст, стандарты и правильное выполнение работы." }
];
var ORDER = ["d","i","s","c"];
var $ = function (s) { return document.querySelector(s); };
var $$ = function (s) { return Array.from(document.querySelectorAll(s)); };
var currentStep=0, answered=[], dragging=null;
var wizard,grid,tabs,dialogEl,bodyEl,barEl,landingEl,resultsEl,tabsEl;
function byKey(k){return TYPES.filter(function(t){return t.key===k;})[0];}
function openWizard(){ wizard.style.display="block"; setTimeout(()=>{ wizard.classList.add("is-open"); },10); window.scrollTo({top:0,behavior:"smooth"});} 
function closeWizard(){ wizard.classList.remove("is-open"); setTimeout(()=>{ if(!wizard.classList.contains("is-open")) wizard.style.display="none"; },250);}
function setStep(n){ n=Math.min(STEPS-1,Math.max(0,n)); currentStep=n; render(); }
function next(){ setStep(currentStep+1); }
function prev(){ setStep(currentStep-1); }
function skipFn(){ setStep(currentStep+1); }
function openResults(){
  resultsEl.classList.remove("hidden");
  wizard.style.display="none";
  wizard.classList.remove("is-open");
  landingEl.classList.add("hidden");
  window.scrollTo({top:0,behavior:"smooth"});
}
function closeResults(){
  resultsEl.classList.add("hidden");
}
function openWizardFromStart(){ openWizard(); }
function closeWizardFromStart(){ closeWizard(); }
function closeWizardFromResults(){ closeWizard(); }
document.addEventListener("DOMContentLoaded",function(){
  elWizard = function(){ return document.getElementById("wizard"); };
  elGrid = function(){ return document.getElementById("grid"); };
  elTabs = function(){ return document.getElementById("tabs"); };
  elDialog = function(){ return document.querySelector(".disc-modal__dialog"); };
  elBody = function(){ return document.querySelector(".disc-modal__body"); };
  elBar = function(){ return document.getElementById("discProgress"); };
  elLanding = function(){ return document.getElementById("landing"); };
  elResults = function(){ return document.getElementById("results"); };
  elTabsEl = elTabs();
  elWizard(); elGrid(); elBody(); elBar(); elLanding(); elResults();
  render();
  wireGlobalListeners();
});
function render(){
  elTabs().querySelectorAll("*").forEach(function(li, i){
    const active = i===currentStep;
    li.classList.toggle("is-active", active);
    li.setAttribute("aria-selected", active ? "true":"false");
  });
  elGrid().innerHTML="";
  QUESTIONS.forEach(function(it, qi){ if(it.step===currentStep) elGrid().appendChild(makeCard(qi)); });
  elBar().style.width=((currentStep+1)/STEPS*100)+"%";
  document.getElementById("prevBtn").disabled=(currentStep===0);
  var nav=elWizard().querySelector(".disc-modal__nav");
  if(currentStep===STEPS-1){ document.getElementById("nextBtn").style.display="none"; document.getElementById("finishBtn").style.display=""; }
  else { document.getElementById("nextBtn").style.display=""; document.getElementById("finishBtn").style.display="none"; }
}
function makeCard(qi){
  var query=QUESTIONS[qi];
  var card=document.createElement("div");
  card.className="item-disc-wrapper";  // keep simple, no id mismatch
  // inner list of 4 items:
  var inner=document.createElement("div");
  inner.className="disc-list--wrap";
  inner.appendChild(makeList(qi, query.items));
  card.appendChild(inner);
  return card;
}
function makeList(qi, items){
  var ul=document.createElement("ul");
  ul.className="disc-list";
  ul.dataset.qi=qi;
  items.forEach(function(item){ ul.appendChild(makeItem(item.type, qi, item.text)); });
  return ul;
}
function makeItem(type, qi, text){
  var li=document.createElement("li");
  li.className="disc-item is-droppable";
  li.dataset.type=type;
  li.dataset.qi=qi;
  li.draggable=true;
  var no=document.createElement("span"); no.className="no";
  var handle=document.createElement("span"); handle.className="handle"; handle.setAttribute("aria-hidden","true");
  handle.innerHTML=handleSvg();
  var t=document.createElement("span"); t.className="text"; t.textContent=text;
  li.appendChild(no); li.appendChild(handle); li.appendChild(t);
  return li;
}
function onKey(e){
  var li = e.target.closest ? e.target.closest(".item") : e.target;
  if(!li||!li.dataset||!li.dataset.qi)return;
  var ul=li.closest("ul");
  if(!ul)return;
  var drag=li.closest(".disc-item")||li;
  if(e.key==="ArrowUp"){
    var idx=Array.from(ul.children).indexOf(drag);
    if(idx>0){ ul.insertBefore(drag, ul.children[idx-1]); e.preventDefault(); }
  } else if(e.key==="ArrowDown"){
    var idx2=Array.from(ul.children).indexOf(drag);
    if(idx2<ul.children.length-1){ ul.insertBefore(drag, ul.children[idx2+1].nextSibling)||ul.appendChild(drag); e.preventDefault(); }
  }
}
function makeSortable(){
  document.body.addEventListener("dragstart",function(e){
    var li=e.target.closest?e.target.closest(".item"):null;
    if(!li)return;
    dragging=li; li.classList.add("disc-item--dragging");
    e.dataTransfer.effectAllowed="move"; e.dataTransfer.setData("text/plain","");
  });
  document.body.addEventListener("dragend",function(){
    if(dragging){ dragging.classList.remove("disc-item--dragging"); dragging=null; }
    collectAnswers();
  });
  document.body.addEventListener("dragover",function(e){
    var ul=e.target.closest?e.target.closest("ul.list"):null;
    if(!ul||!dragging)return;
    e.preventDefault();
    var list=ul.classList.contains("disc-list")?ul:ul.querySelector(".disc-list")||ul;
    var after=afterListElement(list,e.clientY);
    var target=(after)?after.parentElement:ul;
    if(after==null){ target.appendChild(dragging); } else { target.insertBefore(dragging,after);}
  });
  $$("ul.list, ul.disc-list").forEach(function(ul){
    Array.prototype.forEach.call(ul.children,function(li){ li.addEventListener("keydown",onKey); });
  });
}
function afterListElement(ul, y){
  var items=Array.prototype.slice.call(ul.children).filter(function(c){return !c.classList.contains("disc-item--dragging");});
  var center=items.map(function(c){ var r=c.getBoundingClientRect(); return r.top+r.height/2; });
  for(var i=0;i<center.length;i++){ if(y<center[i])return items[i]; }
  return null;
}
function collectAnswers(){
  answered=[];
  $$("ul.list, ul.disc-list").forEach(function(ul){ var order=[]; Array.prototype.forEach.call(ul.children,function(el){ order.push(el.dataset.type); }); answered[parseInt(ul.dataset.qi,10)]=order; });
}
function score(){
  var maj={d:0,i:0,s:0,c:0}; var min={d:0,i:0,s:0,c:0};
  QUESTIONS.forEach(function(query,qi){ var arr=answered[qi]; if(!arr||arr.length<1)return; if(arr[0])maj[arr[0]]=maj[arr[0]]||0; if(arr[arr.length-1])min[arr[arr.length-1]]=min[arr[arr.length-1]]||0; });
  var out={}; ORDER.forEach(function(k){ out[k]=((maj[k]||0)-(min[k]||0)); }); return out;
}
function showResults(){
  collectAnswers();
  var s=score();
  var ranked=ORDER.slice().sort(function(a,b){ return s[b]-s[a]; });
  var bestKey=ranked[0];
  var best=byKey(bestKey);
  $$(".card-scores .row").forEach(function(el){
    var k=el.dataset.type; el.querySelector(".val").textContent=(s[k]>0?"+":"")+s[k];
  });
  document.querySelector(".disc__result-top .disc__result-desc").innerHTML="<strong>Доминирующий тип «"+best.name+"»:</strong> "+best.full;
  $$(".results-card .results-row .disc__result-scores .disc__row").forEach(function(el){
    var k=el.dataset.type; el.querySelector(".disc__row-val").textContent=s[k];
  });
}
function handleSvg(){ return '<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="5" cy="3" r="1.4" fill="currentColor"/><circle cx="11" cy="3" r="1.4" fill="currentColor"/><circle cx="5" cy="8" r="1.4" fill="currentColor"/><circle cx="11" cy="8" r="1.4" fill="currentColor"/><circle cx="5" cy="13" r="1.4" fill="currentColor"/><circle cx="11" cy="13" r="1.4" fill="currentColor"/></svg>'; }
function startAgain(){ closeResults(); wizard.style.display="block"; setTimeout(()=>{ wizard.classList.add("is-open"); },10); window.scrollTo({top:0,behavior:"smooth"}); }
function loadInitial(){ window.scrollTo({top:0,behavior:"smooth"}); }
function wireGlobalListeners(){
  var btns=document.querySelectorAll(".btn[data-disc-open], a[data-disc-open], [data-disc-open]");
  $$("[data-disc-open]").forEach(function(el){ el.addEventListener("click",function(e){ e.preventDefault(); openWizard(); }); });
  $$("[data-disc-close]").forEach(function(el){ el.addEventListener("click",function(e){ e.preventDefault(); closeWizard(); }); });
  if(document.getElementById("nextBtn")) document.getElementById("nextBtn").addEventListener("click",next);
  if(document.getElementById("prevBtn")) document.getElementById("prevBtn").addEventListener("click",prev);
  if(document.getElementById("skipBtn")) document.getElementById("skipBtn").addEventListener("click",skipFn);
  if(document.getElementById("finishBtn")) document.getElementById("finishBtn").addEventListener("click",showResults);
  document.getElementById("openBtn").addEventListener("click",function(e){ e.preventDefault(); openWizard(); });
  document.getElementById("restartBtn").addEventListener("click",function(e){ e.preventDefault(); showResults(); });
  document.addEventListener("keydown",function(ev){ if(ev.key==="Escape"){ closeWizard(); if(resultsEl && !resultsEl.classList.contains("hidden")){ showResults(); } } });
  makeSortable();
  render();
}
`;

