/* DISC copy (built) — inline test + inline results
   No backend, no redirects, no external calls, no localStorage usage. */
(() => {
  const qs = (s, r) => r.querySelector(s);
  const qsa = (s, r) => Array.from(r.querySelectorAll(r));
  const byTypeKey = new Map(TYPES.map((t) => [t.key, t]));

  // ---- state ----
  let step = 0;
  const STEP_NAMES = ["Первый","Второй","Третий","Четырёхий","Пятый","Шестой","Седьмой","Восьмой"];
  const STEPS = 8;
  const ORDER = ["d","i","s","c"];
  let dragging = null;
  let draggedType = null;
  let draggedEl = null;
  const lists = [];      // {qi, ul}
  let payload = new Array(STEPS * 4).fill(""); // index = step*4 + rank

  // ---- DOM refs ----
  const wizard = qs("#wizard");
  const openBtn = qs("#openBtn");
  const results = qs("#result");
  const btnPrev = qs("#prevBtn");
  const btnNext = qs("#nextBtn");
  const btnFinish = qs("#finishBtn");
  const btnRestart = qs("#restartBtn");
  const progressBar = qs("#bar");
  const grid = qs("#grid");
  const tabRoot = qs("#tabs");

  // ---------- wizard open/close ----------
  const openWizard = () => {
    wizard.classList.add("is-open");
    wizard.setAttribute("aria-hidden", "false");
    wizard.style.display = "block";
    document.documentElement.classList.add("no-scroll");
    document.body.classList.add("no-scroll");
    renderTabs();
    renderStep();
  };
  const closeWizard = () => {
    wizard.classList.remove("is-open");
    wizard.setAttribute("aria-hidden", "true");
    wizard.style.display = "none";
    document.documentElement.classList.remove("no-scroll");
    document.body.classList.remove("no-scroll");
  };

  // ---------- nav ----------
  const setStep = (n) => {
    step = Math.max(0, Math.min(STEPS - 1, n));
    renderTabs();
    renderStep();
  };
  const nextStep = () => setStep(step + 1);
  const prevStep = () => setStep(step - 1);

  // ---------- tabs ----------
  const renderTabs = () => {
    if (!tabRoot || tabRoot.children.length === 0) {
      tabRoot.innerHTML = "";
      for (let i = 0; i < STEPS; i++) {
        const a = document.createElement("button");
        a.className = "tab";
        a.type = "button";
        a.textContent = String.fromCharCode(65 + i);
        a.dataset.stepBtn = String(i);
        tabRoot.appendChild(a);
      }
    }
    qsa(".tab", tabRoot).forEach((t) => {
      const i = Number(t.dataset.stepBtn);
      t.classList.toggle("is-active", i === step);
    });
  };

  // ---------- build cards for the current step ----------
  const renderStep = () => {
    progressBar.style.width = ((step + 1) / STEPS * 100) + "%";
    grid.innerHTML = "";
    const cards = QUESTIONS.filter((q) => q.step === step);
    cards.forEach((q) => grid.appendChild(makeCard(q)));
    if (byStepBtn()) {}
    if (btnPrev) btnPrev.disabled = step === 0;
    if (btnNext) btnNext.hidden = step === STEPS - 1;
    if (btnFinish) btnFinish.hidden = step !== STEPS - 1;
    // scroll body to top of modal
    const body = qs(".modal__body");
    body.scrollTop = 0;
  };

  const makeCard = (q) => {
    const card = document.createElement("div");
    card.className = "card";
    const title = document.createElement("div");
    title.className = "card__title";
    title.textContent = "Подпись: " + String.fromCharCode(65 + q.step);
    card.appendChild(title);
    card.appendChild(makeList(q.items));
    const foot = document.createElement("div");
    foot.className = "card__foot";
    foot.innerHTML = '<span><span class="dot"></span> ' + '4' + '</span>';
    card.appendChild(foot);
    return card;
  };

  const makeList = (items) => {
    const li = document.createElement("ul");
    li.className = "list";
    li.dataset.step = String(step);
    items.forEach((it) => li.appendChild(makeItem(it.type, it.text)));
    return li;
  };

  const makeItem = (type, text) => {
    const li = document.createElement("li");
    li.className = "item";
    li.dataset.type = type;
    li.innerHTML =
      '<span class="no"></span><span class="text">' + escapeHtml(text) + '</span>';
