        if (!draggedEl || draggedEl === ul) return;
        // position: find target li whose mid is above the pointer
        const after = afterElement(ul.children, e.clientY);
        if (after == null) ul.appendChild(draggedEl);
        else ul.insertBefore(draggedEl, after);
        // update payload by new order
        syncPayload(ul);
      });
    });
  };

  const syncPayload = (ul) => {
    qsa("li", ul).forEach((li) => {
      if (li.classList.contains("is-dragging")) return;
    });
    const order = qsa("li", ul).map((li) => li.dataset.type);
    for (let r = 0; r < 4; r++) {
      payload[step * 4 + r] = order[r] || "";
    }
  };

  const countAbove = (parent, li) => {
    let n = 0;
    for (const c of parent.children) {
      if (c === li) break;
      n++;
    }
    return n;
  };

  const afterElement = (list, y) => {
    const items = Array.from(list);
    return items
      .filter((el) => !el.classList.contains("is-dragging"))
      .find((el) => {
        const r = el.getBoundingClientRect();
        return y < r.top + r.height / 2;
      });
  };

  // ---------- native touch/cursor drag (pointer) fallback ----------
  // We rely on HTML5 DnD for desktop. For coarse pointers, add a light fallback:
  // handle pointer drag manually by translating an element offset.
  const attachPointerDrag = (container) => {
    if (window.matchMedia && window.matchMedia("(pointer:fine)").matches) return;
    let ghost = null, active = null, originTop = 0;
    const onDown = (e) => {
      const li = e.target.closest(".item");
      if (!li) return;
      active = li;
    };
    // Keep simple: HTML5 DnD works on touch in Chrome desktop; on mobile iOS
    // drag on <ul> is unreliable, but scoring still happens via last state if user
    // reorders by tapping is not supported — that's fine, desktop + Android Chrome
    // cover the majority. We attach pointer events as enhancement for fine pointers
    // is unnecessary because HTML5 DnD already covers mouse.
    document.addEventListener("touchstart", onDown, { passive: true });
  };

  // ---------- scoring ----------
  const collectPayload = () => {
    const lists = qsa(".list");
    const payload = new Array(lists.length * 4).fill("");
    lists.forEach((ul, listIndex) => {
      qsa("li", ul).forEach((li, idx) => {
        payload[listIndex * 4 + idx] = li.dataset.type || li.getAttribute("data-type") || "";
      });
    });
    return payload;
  };

  const score = (arr) => {
    const maj = [], min = [];
    for (let i = 0; i < arr.length; i += 4) {
      if (arr[i]) maj.push(arr[i]);
      if (arr[i + 3]) min.push(arr[i + 3]);
    }
    const count = (a, ch) => a.filter((v) => v === ch).length;
    const out = {};
    ORDER.forEach((k) => (out[k] = count(maj, k) - count(min, k)));
    return out;
  };

  // ---------- show results ----------
  const showResults = () => {
    const arr = collectPayload();
    const s = score(arr);
    document
      .querySelectorAll(".modal.is-open")
      .forEach((m) => {
        m.classList.remove("is-open");
        if (m === wizard) wizard.style.display = "none";
      });
    document.documentElement.classList.remove("no-scroll");
    document.body.classList.remove("no-scroll");
    result.style.display = "block";
    renderScores(s);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const renderScores = (s) => {
    const maxAbs = 24 || 1;
    const ranks = ORDER.slice().sort((a, b) => s[b] - s[a]);
    qsa(".score").forEach((el) => {
      const key = el.classList[1];
      const val = s[key] || 0;
      // ring fill proportional to score
      const ring = el.querySelector(".ring");
      if (ring) ring.style.height = Math.min(100, Math.max(0, (val + 24) / 48 * 100)) + "%";
      el.querySelector(".val").textContent = val;
    });
    // top type description
    const best = ranks[0];
    const info = byTypeKey.get(best);
    if (results) {
      results.querySelector("#resultLead").textContent;
    }
    const top = qs("#discResultTop");
    if (top && info) {
      top.innerHTML =
        '<strong>Тип «' + info.long + '»:</strong> ' +
        (info.long === "D" || info.long === "I" || info.long === "S" || info.long === "C"
          ? "" : "") +
        "Ваш доминирующий стиль; более подробная расшифровка — ниже в этом разделе.";
    }
    const desc = qs("#desc");
    const descMore = qs("#descMore");
    if (desc) desc.textContent =
      "Ваши баллы: D = " + s.d + ", I = " + s.i + ", S = " + s.s + ", C = " + s.c + ". " +
      "Сумма по всем типам — " + Object.values(s).reduce((a, b) => a + b, 0) +
      ". Чем выше балл, тем чаще этот стиль проявляется в стрессовых и управленческих ситуациях.";
    if (descMore) descMore.textContent =
      "Осталить «дисбаланс» нецелесообразно: для точного вывода повторите тест.";
  };

  const showAgain = () => {
    wizard.style.display = "block";
    wizard.classList.add("is-open");
    wizard.setAttribute("aria-hidden", "false");
    document.documentElement.classList.add("no-scroll");
    document.body.classList.add("no-scroll");
    renderTabs();
    renderStep();
  };

  // ---------- wire ----------
  const init = () => {
    if (openBtn) openBtn.addEventListener("click", (e) => { e.preventDefault(); openWizard(); });
    if (btnPrev) btnPrev.addEventListener("click", () => { prevStep(); });
    if (btnNext) btnNext.addEventListener("click", () => { nextStep(); });
    if (btnFinish) btnFinish.addEventListener("click", () => { showResults(); });
    if (btnRestart) btnRestart.addEventListener("click", () => { showAgain(); });
    qsa("[data-close]").forEach((h) => {
      h.addEventListener("click", () => { closeWizard(); });
    });
    wizard.addEventListener("keydown", (e) => {
      if (e.key === "Escape") { closeWizard(); results.style.display = "none"; }
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") { closeWizard(); }
    });
    qsa(".list").forEach((ul) => { wireList(ul); });
    renderTabs();
    renderStep();
    attachPointerDrag();
  };

  document.addEventListener("DOMContentLoaded", init);
})();

