(() => {
  const qs = (s, r) => r.querySelector(s);
  const qsa = (s, r) => Array.from(r.querySelectorAll(r || document));
  const byKey = new Map(TYPES.map((t) => [t.key, t]));
  const STEP_NAMES = ["Первый", "Второй", "Третий", "Четырёхий", "Пятый", "Шестой", "Седьмой", "Восьмой"];
  const STEPS = 8;
  const ORDER = ["d", "i", "s", "c"];
  const HANDLE_SVG = '<svg width="14" height="14" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><circle cx="4" cy="3" r="1.3"/><circle cx="10" cy="3" r="1.3"/><circle cx="4" cy="8" r="1.3"/><circle cx="10" cy="8" r="1.3"/><circle cx="4" cy="13" r="1.3"/><circle cx="10" cy="13" r="1.3"/></svg>';

  let step = 0;
  let draggedEl = null, draggedType = null;
  let payload = new Array(STEPS * 4).fill("");

  const wizard = qs("#wizard");
  const openBtn = qs("#openBtn");
  const results = qs("#result");
  const btnPrev = qs("#prevBtn");
  const btnNext = qs("#nextBtn");
  const btnFinish = qs("#finishBtn");
  const btnRestart = qs("#restartBtn");
  const progressBar = qs("#bar");
  const grid = qs("#grid");
  const tabRoot = qs("#tabs");

  const openWizard = () => {
    wizard.classList.add("is-open"); wizard.setAttribute("aria-hidden", "false"); wizard.style.display = "block";
    document.documentElement.classList.add("no-scroll"); document.body.classList.add("no-scroll");
    renderTabs(); renderStep();
  };
  const closeWizard = () => {
    wizard.classList.remove("is-open"); wizard.setAttribute("aria-hidden", "true"); wizard.style.display = "none";
    document.documentElement.classList.remove("no-scroll"); document.body.classList.remove("no-scroll");
  };
  const setStep = (n) => { step = Math.max(0, Math.min(STEPS - 1, n)); renderTabs(); renderStep(); };
  const nextStep = () => setStep(step + 1);
  const prevStep = () => setStep(step - 1);

  const renderTabs = () => {
    if (tabRoot.children.length === 0) {
      for (let i = 0; i < STEPS; i++) {
        const a = document.createElement("button");
        a.className = "tab"; a.type = "button";
        a.textContent = String.fromCharCode(65 + i);
        a.dataset.stepBtn = String(i);
        tabRoot.appendChild(a);
      }
    }
    qsa(".tab", tabRoot).forEach((t) => {
      const i = Number(t.dataset.stepBtn);
      t.classList.toggle("is-active", i === step);
    });
  };

  const renderStep = () => {
    progressBar.style.width = ((step + 1) / STEPS * 100) + "%";
    grid.innerHTML = "";
    QUESTIONS.filter((q) => q.step === step).forEach((q) => grid.appendChild(makeCard(q)));
    if (btnPrev) btnPrev.disabled = step === 0;
    if (btnNext) btnNext.hidden = step === STEPS - 1;
    if (btnFinish) btnFinish.hidden = step !== STEPS - 1;
    qs(".modal__body").scrollTop = 0;
  };

  const makeCard = (q) => {
    const card = document.createElement("div"); card.className = "card";
    const title = document.createElement("div"); title.className = "card__title";
    title.textContent = "Подпись: " + String.fromCharCode(65 + q.step);
    card.appendChild(title);
    card.appendChild(makeList(q.items));
    const foot = document.createElement("div"); foot.className = "card__foot";
    foot.innerHTML = '<span><span class="dot"></span> <span>4</span></span>';
    card.appendChild(foot);
    return card;
  };
  const makeList = (items) => {
    const ul = document.createElement("ul"); ul.className = "list"; ul.dataset.step = String(step);
    items.forEach((it) => ul.appendChild(makeItem(it.type, it.text)));
    return ul;
  };
  const makeItem = (type, text) => {
    const li = document.createElement("li"); li.className = "item"; li.dataset.type = type;
    const no = document.createElement("span"); no.className = "no";
    const handle = document.createElement("span"); handle.className = "handle"; handle.innerHTML = HANDLE_SVG; handle.setAttribute("aria-hidden", "true");
    const t = document.createElement("span"); t.className = "text"; t.textContent = text;
    li.appendChild(no); li.appendChild(handle); li.appendChild(t); return li;
  };

  const wireList = (ul) => {
    qsa("li", ul).forEach((li) => {
      li.setAttribute("draggable", "true");
      li.addEventListener("dragstart", (e) => {
        draggedEl = li; draggedType = li.dataset.type;
        payload[step * 4 + countAbove(ul, li)] = draggedType;
        li.classList.add("is-dragging"); e.dataTransfer.effectAllowed = "move"; e.dataTransfer.setData("text/plain", draggedType || "");
      });
      li.addEventListener("dragend", () => { draggedEl = null; draggedType = null; });
      li.addEventListener("dragover", (e) => { e.preventDefault(); });
      li.addEventListener("drop", (e) => {
        e.preventDefault();
        if (!draggedEl) return;
        const after = afterElement(ul.children, e.clientY);
        (after == null ? ul.appendChild(draggedEl) : ul.insertBefore(draggedEl, after));
        syncPayload(ul);
      });
    });
  };
  const countAbove = (parent, li) => { let n = 0; for (const c of parent.children) { if (c === li) break; n++; } return n; };
  const afterElement = (list, y) => Array.from(list).filter((el) => !el.classList.contains("is-dragging")).find((el) => { const r = el.getBoundingClientRect(); return y < r.top + r.height / 2; });
  const syncPayload = (ul) => {
    const order = qsa("li", ul).map((li) => li.dataset.type);
    for (let r = 0; r < 4; r++) payload[step * 4 + r] = order[r] || "";
  };

  const collectPayload = () => {
    const arr = new Array(qsa(".list").length * 4).fill("");
    qsa(".list").forEach((ul, li) => { qsa("li", ul).forEach((el, idx) => { arr[li * 4 + idx] = el.dataset.type || ""; }); });
    return arr;
  };
  const score = (arr) => {
    const maj = [], min = [];
    for (let i = 0; i < arr.length; i++) if (arr[i]) { if (i % 4 === 0) maj.push(arr[i]); if (i % 4 === 3) min.push(arr[i]); }
    const c = (a, ch) => a.filter((v) => v === ch).length;
    const out = {}; ORDER.forEach((k) => { out[k] = c(maj, k) - c(min, k); }); return out;
  };

  const showResults = () => {
    const s = score(collectPayload());
    showScores(s);
    wizard.style.display = "none"; wizard.classList.remove("is-open"); wizard.setAttribute("aria-hidden", "true");
    document.documentElement.classList.remove("no-scroll"); document.body.classList.remove("no-scroll");
    results.style.display = "block"; results.setAttribute("hidden", ""); scrollTo({ top: 0, behavior: "smooth" });
  };
  const showScores = (s) => {
    qsa(".score").forEach((el) => {
      const key = el.classList[1]; const val = s[key] || 0;
      const ring = el.querySelector(".ring"); if (ring) ring.style.height = Math.min(100, Math.max(0, (val + 24) / 48 * 100)) + "%";
      el.querySelector(".val").textContent = val;
    });
    const ranks = ORDER.slice().sort((a, b) => s[b] - s[a]);
    const top = qs("#discResultTop"); const best = ranks[0]; const info = byKey.get(best);
    if (top && info) top.innerHTML = "<strong>Тип «" + info.long + "» strongest style</strong>";
    const desc = qs("#desc");
    if (desc) desc.textContent = "Ваши баллы: D = " + s.d + ", I = " + s.i + ", S = " + s.s + ", C = " + s.c + ". Сумма = " + Object.values(s).reduce((a, b) => a + b, 0) + ". Более высокий балл — чаще проявляемый стиль.";
  };
  const showAgain = () => { openWizard(); };

  const init = () => {
    if (openBtn) openBtn.addEventListener("click", (e) => { e.preventDefault(); openWizard(); });
    if (btnPrev) btnPrev.addEventListener("click", prevStep);
    if (btnNext) btnNext.addEventListener("click", nextStep);
    if (btnFinish) btnFinish.addEventListener("click", showResults);
    if (btnRestart) btnRestart.addEventListener("click", showAgain);
    qsa("[data-close]").forEach((h) => { h.addEventListener("click", () => { closeWizard(); results.style.display = "none"; }); });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") { closeWizard(); results.style.display = "none"; } });
    qsa(".list").forEach((ul) => { wireList(ul); });
    renderTabs(); renderStep();
  };
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();

