const fs = require("fs");
const h = fs.readFileSync("/home/dp/MyProjects/disc/index.html", "utf8");
const s = h.indexOf("var DATA = [") + "var DATA = [".length;
const e = h.lastIndexOf("]");
const arrStr = h.slice(s, e + 1);
let arr;
try {
  arr = JSON.parse(arrStr);
} catch (err) {
  console.log("parse error:", err.message);
  process.exit(1);
}
console.log("parsed", arr.length, "items");
console.log("Q0:", JSON.stringify(arr[0]));
console.log("Q23:", JSON.stringify(arr[arr.length - 1]));
// compare against canonical
const canon = JSON.parse(
  fs.readFileSync("/home/dp/MyProjects/disc/test-assignment/reference/questions.json", "utf8")
).questions;
const a = (obj) => obj.items.map((it) => it.text).join("|");
const b = (obj) => obj.items.map((it) => it.text).join("|");
let mism = 0;
for (let i = 0; i < Math.min(arr.length, canon.length); i++) {
  const ta = a(arr[i]);
  const tc = b(canon[i]);
